using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Set up options with a known type resolver (source-gen context for Person).
var options = new JsonSerializerOptions
{
    TypeInfoResolver = AppJsonContext.Default
};

// 1️⃣  Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly.
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got typed metadata for Person – kind: {personInfo.Kind}");

// 2️⃣  Probe without throwing: TryGetTypeInfo returns false if metadata isn't available.
bool found = options.TryGetTypeInfo(typeof(UnknownType), out JsonTypeInfo? info);
Console.WriteLine($"Metadata for UnknownType available? {found}");  // false

// Also show the happy-path probe:
bool foundPerson = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? personInfo2);
Console.WriteLine($"Metadata for Person available? {foundPerson}, kind: {personInfo2?.Kind}");

public record Person(string Name, int Age);

// A type the resolver knows nothing about.
public class UnknownType { }

[JsonSerializable(typeof(Person))]
internal partial class AppJsonContext : JsonSerializerContext { }

